      {
        "panahon": "1859",
        "pangyayari": "Pagsasabatas ng Lupa",
        "detalye": "Inaprubahan ng New York State Legislature ang pagtatalaga ng lupa para sa isang malaking pampublikong parke sa Lungsod ng Brooklyn (na noon ay isang hiwalay na lungsod mula sa New York)."
      },
      {
        "panahon": "1866",
        "pangyayari": "Pagkuha kina Olmsted at Vaux",
        "detalye": "Matapos ang Digmaang Sibil, opisyal na kinuha sina Frederick Law Olmsted at Calvert Vaux upang idisenyo ang parke. Binago nila ang orihinal na plano upang mas mapakinabangan ang natural na topograpiya ng lupa."
      },
      {
        "panahon": "1867",
        "pangyayari": "Opisyal na Pagbubukas",
