      },
      {
        "panahon": "1873",
        "pangyayari": "Pagkumpleto ng Pangunahing Disenyo",
        "detalye": "Natapos ang karamihan sa mga pangunahing elemento ng disenyo nina Olmsted at Vaux, kabilang ang Long Meadow, ang Lake, at ang Ravine."
      },
      {
        "panahon": "Kalagitnaan ng ika-20 Siglo",
        "pangyayari": "Panahon ng Pagbaba",
        "detalye": "Dahil sa mga pagbawas sa badyet ng lungsod at pagbabago sa mga prayoridad, napabayaan ang parke. Maraming bahagi nito ang nasira at hindi na ligtas."
      },
      {
        "panahon": "1987",
        "pangyayari": "Pagtatag ng Prospect Park Alliance",
        "detalye": "Itinatag ang Prospect Park Alliance, isang non-profit na organisasyon, sa pakikipagtulungan sa Lungsod ng New York. Ang kanilang misyon ay pangalagaan, ibalik sa dati, at pagandahin ang parke."
      },
      {
        "panahon": "Huling bahagi ng ika-20 Siglo hanggang Kasalukuyan",
        "pangyayari": "Muling Pagsilang at Revitalization",
        "detalye": "Sa pamamagitan ng pagsisikap ng Alliance at ng komunidad, sumailalim ang parke sa malawakang restorasyon. Ang mga makasaysayang istruktura ay inayos, ang mga tanawin ay pinanumbalik, at nagkaroon ng mga bagong programa para sa publiko. Ngayon, ito ay isang masigla at minamahal na sentro ng komunidad."
      }
    ],
    "mahahalagang_bahagi_at_katangian": [
      {
        "pangalan": "Long Meadow",
        "deskripsyon": "Isang malawak na damuhan na may habang halos isang milya (1.6 km). Ito ay idinisenyo upang magbigay ng isang payapa at malawak na tanawin na katulad ng sa kanayunan."
      },
      {
        "pangalan": "The Ravine",
        "deskripsyon": "Ang tanging natitirang kagubatan sa Brooklyn. Ito ay may masalimuot na sistema ng mga sapa at talon na idinisenyo upang gayahin ang isang liblib na lambak sa kabundukan."
      },
      {
        "pangalan": "Prospect Park Lake",
        "deskripsyon": "Isang 60-acre na lawa na siyang pinakamalaking anyong tubig sa Brooklyn. Ito ay tahanan ng iba't ibang uri ng ibon at hayop."
      },
      {
        "pangalan": "Grand Army Plaza",
        "deskripsyon": "Ang maringal na hilagang pasukan ng parke, na nagtatampok sa Soldiers' and Sailors' Arch, isang monumento para sa mga sundalo ng Union Army noong Digmaang Sibil."
      },
      {
        "pangalan": "Boathouse at Audubon Center",
        "deskripsyon": "Isang makasaysayang gusali na may istilong Beaux-Arts na ngayon ay nagsisilbing unang urban Audubon Center sa bansa, na nakatuon sa edukasyon tungkol sa kalikasan."
      }
    ],
    "kahalagahan_sa_kasalukuyan": "Ang Prospect Park ay nananatiling 'puso ng Brooklyn'. Ito ay isang mahalagang espasyo para sa libangan, pagpapahinga, mga kaganapang pangkultura tulad ng BRIC Celebrate Brooklyn! Festival, at pagtitipon ng komunidad. Ang patuloy na pangangalaga ng Prospect Park Alliance ay tinitiyak na mananatili itong isang yaman para sa mga susunod na henerasyon."
  }
}
```

